package com.aadil.ecommerce.entities;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import java.math.BigDecimal;@Table(name = "order_items")@Entity@Getter@Setter@NoArgsConstructorpublic class OrderItemEntity {    @GeneratedValue(strategy = GenerationType.IDENTITY)    @Id    @Column(name = "item_id")    private Long itemId;    @ManyToOne(fetch = FetchType.LAZY,targetEntity = OrderEntity.class)    @JoinColumn(name = "order_id",nullable = false)    private OrderEntity order;    @ManyToOne(fetch = FetchType.LAZY,targetEntity = ProductEntity.class)    @JoinColumn(name = "product_id",nullable = false)    private ProductEntity product;    @Column(nullable = false)    private Integer quantity;    @Column(nullable = false)    private BigDecimal unitPrice;}